package com.amplayer.portable;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public class World20116Instrumentation extends Instrumentation {
 private void report(String key,String text){Bundle b=new Bundle();b.putString(key,text);sendStatus(0,b);}
 private byte[] read(String name){try{return java.nio.file.Files.readAllBytes(new File(getTargetContext().getFilesDir(),name).toPath());}catch(Exception e){return null;}}
 private void restore(String name,byte[] bytes)throws Exception{File file=new File(getTargetContext().getFilesDir(),name);if(bytes==null)file.delete();else java.nio.file.Files.write(file.toPath(),bytes);}
 private JSONObject update(String provider)throws Exception{JSONObject prefs=Store.load(getTargetContext()).put("autoUpdate",false).put("primarySource",provider).put("fallback",false);Store.save(getTargetContext(),prefs.toString());CountDownLatch done=new CountDownLatch(1);CatalogUpdater.update(getTargetContext(),value->done.countDown());if(!done.await(180,TimeUnit.SECONDS))throw new Exception("Update timeout "+provider);JSONObject status=CatalogUpdater.status(getTargetContext());if(!status.optBoolean("ok")||!provider.equals(status.optString("provider")))throw new Exception("Source failed "+status);return CatalogUpdater.cache(getTargetContext());}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();byte[] settings=read("settings.json"),cache=read("catalog-cache.json"),status=read("update-status.json");try{
  JSONObject feed=new JSONObject().put("format","m3u").put("country","GB").put("region","INT");JSONArray gb=CatalogUpdater.parseFeed(getTargetContext(),"#EXTM3U\n#EXTINF:-1,Jazz\nhttps://example.test/gb\n",feed,"alon");if(!"GB".equals(gb.getJSONObject(0).optString("country")))throw new Exception("M3U country missing");
  feed.put("country","FR");JSONArray fr=CatalogUpdater.parseFeed(getTargetContext(),"#EXTM3U\n#EXTINF:-1,Jazz\nhttps://example.test/fr\n",feed,"alon");if(fr.getJSONObject(0).getString("id").equals(gb.getJSONObject(0).getString("id")))throw new Exception("Countries shared same station ID");
  JSONObject open=new JSONObject().put("stations",new JSONArray().put(new JSONObject().put("name","Open Test").put("country","HK").put("streamURL","https://example.test/hk")));JSONArray parsed=CatalogUpdater.parseFeed(getTargetContext(),open.toString(),new JSONObject().put("format","openstations"),"openstations");if(!"HK".equals(parsed.getJSONObject(0).optString("country")))throw new Exception("Open JSON failed");
  JSONObject web=new JSONObject().put("row",new JSONObject().put("Name","Web Test").put("Country","Germany").put("Genre",new JSONArray().put("Jazz")).put("StreamUri","https://example.test/de"));parsed=CatalogUpdater.parseFeed(getTargetContext(),web.toString(),new JSONObject().put("format","webradiodb"),"webradiodb");if(!"DE".equals(parsed.getJSONObject(0).optString("country")))throw new Exception("Country names failed");if(CatalogUpdater.publicStream("http://127.0.0.1/live"))throw new Exception("Private remote source accepted");report("parsers","PASS country-aware M3U, OpenStations JSON, WebradioDB JSON and private-address rejection");
  JSONObject downloaded=update("openstations");if(downloaded.getJSONArray("stations").length()<50||downloaded.optInt("countryCount")<8)throw new Exception("OpenStations incomplete");report("openstations","PASS live one-click download "+downloaded.getJSONArray("stations").length()+" entries, "+downloaded.optInt("countryCount")+" countries");
  downloaded=update("webradiodb");if(downloaded.getJSONArray("stations").length()<100||downloaded.optInt("countryCount")<20)throw new Exception("WebradioDB incomplete");report("webradiodb","PASS live one-click download "+downloaded.getJSONArray("stations").length()+" entries, "+downloaded.optInt("countryCount")+" countries");
  downloaded=update("alon");JSONArray stations=downloaded.getJSONArray("stations");if(stations.length()>6000||downloaded.optInt("countryCount")<100)throw new Exception("World coverage incomplete: "+downloaded);Set<String> urls=new HashSet<>();for(int i=0;i<stations.length();i++)if(!urls.add(stations.getJSONObject(i).getString("url")))throw new Exception("Duplicate URL");report("globalUpdate","PASS live concurrent global download "+stations.length()+" entries, "+downloaded.optInt("countryCount")+" countries; no duplicate URLs");result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{try{restore("settings.json",settings);restore("catalog-cache.json",cache);restore("update-status.json",status);}catch(Exception ignored){}}}
}
